{
  "name": "myproject",
  "version": "1.0.0",
  "description": "Convex Multi-Field Indexes project",
  "main": "index.js",
  "scripts": {
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "dependencies": {
    "convex": "^1.12.0"
  },
  "devDependencies": {
    "typescript": "^5.0.0"
  }
}

import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  products: defineTable({
    runId: v.string(),
    name: v.string(),
    category: v.string(),
    price: v.number(),
    inStock: v.boolean(),
  })
    .index("by_runId_and_category", ["runId", "category"])
    .index("by_runId_category_price", ["runId", "category", "price"]),
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

export const seed = mutation({
  args: { runId: v.string() },
  handler: async (ctx, args) => {
    await ctx.db.insert("products", {
      runId: args.runId,
      name: "Smartphone",
      category: "Electronics",
      price: 500,
      inStock: true,
    });
    await ctx.db.insert("products", {
      runId: args.runId,
      name: "Laptop",
      category: "Electronics",
      price: 1500,
      inStock: true,
    });
    await ctx.db.insert("products", {
      runId: args.runId,
      name: "Headphones",
      category: "Electronics",
      price: 150,
      inStock: false,
    });
    await ctx.db.insert("products", {
      runId: args.runId,
      name: "T-Shirt",
      category: "Clothing",
      price: 25,
      inStock: true,
    });
    await ctx.db.insert("products", {
      runId: args.runId,
      name: "Book",
      category: "Books",
      price: 15,
      inStock: true,
    });
  },
});

export const getByCategory = query({
  args: {
    runId: v.string(),
    category: v.string(),
  },
  handler: async (ctx, args) => {
    return await ctx.db
      .query("products")
      .withIndex("by_runId_and_category", (q) =>
        q.eq("runId", args.runId).eq("category", args.category)
      )
      .collect();
  },
});

export const getCheapByCategory = query({
  args: {
    runId: v.string(),
    category: v.string(),
    maxPrice: v.number(),
  },
  handler: async (ctx, args) => {
    return await ctx.db
      .query("products")
      .withIndex("by_runId_category_price", (q) =>
        q
          .eq("runId", args.runId)
          .eq("category", args.category)
          .lte("price", args.maxPrice)
      )
      .collect();
  },
});
